package com.rgv.tradingbot.websocket;

import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;
import org.springframework.web.socket.CloseStatus;
import org.springframework.web.socket.TextMessage;
import org.springframework.web.socket.WebSocketSession;
import org.springframework.web.socket.handler.TextWebSocketHandler;

import java.io.IOException;
import java.util.Set;
import java.util.concurrent.CopyOnWriteArraySet;

/**
 * Pushes live TradeSignalDTO updates (BUY/SELL/HOLD signals generated by
 * StrategyEngine) to connected clients, so the frontend can show signals
 * in real time as TradingScheduler's cycle runs.
 *
 * Registered against a WebSocket endpoint (e.g. "/ws/signals") in
 * WebSocketConfig.
 */
@Slf4j
@Component
public class TradeSignalWebSocketHandler extends TextWebSocketHandler {

    private final Set<WebSocketSession> sessions = new CopyOnWriteArraySet<>();
    private final ObjectMapper objectMapper;

    public TradeSignalWebSocketHandler(ObjectMapper objectMapper) {
        this.objectMapper = objectMapper;
    }

    @Override
    public void afterConnectionEstablished(WebSocketSession session) {
        sessions.add(session);
        log.info("Trade signal stream client connected: {}", session.getId());
    }

    @Override
    public void afterConnectionClosed(WebSocketSession session, CloseStatus status) {
        sessions.remove(session);
        log.info("Trade signal stream client disconnected: {} ({})", session.getId(), status);
    }

    /**
     * Serializes the given payload (typically a TradeSignalDTO) to JSON
     * and sends it to every connected session.
     */
    public void broadcast(Object payload) {
        if (sessions.isEmpty()) {
            return;
        }

        try {
            String json = objectMapper.writeValueAsString(payload);
            TextMessage message = new TextMessage(json);

            for (WebSocketSession session : sessions) {
                sendSafely(session, message);
            }
        } catch (IOException ex) {
            log.error("Failed to serialize trade signal payload: {}", ex.getMessage(), ex);
        }
    }

    private void sendSafely(WebSocketSession session, TextMessage message) {
        try {
            if (session.isOpen()) {
                session.sendMessage(message);
            }
        } catch (IOException ex) {
            log.warn("Failed to send trade signal to session {}: {}", session.getId(), ex.getMessage());
        }
    }
}